def family_init(ctx):
    ctx.e = ctx.indicator("ema", period=int(ctx.p.ema_n))


def signal(ctx, i):
    e = ctx.e[i]
    if e is None:
        return 0
    o, h, l, c = ctx.o[i], ctx.h[i], ctx.l[i], ctx.c[i]
    rng = h - l
    if rng <= 0:
        return 0
    if c <= e:
        return 0
    eps = float(ctx.p.eps_frac) * rng
    ps = int(ctx.p.pset)
    if (ps & 1) and abs(h - o) <= eps and abs(c - l) <= eps and c < o:
        return 1
    if (ps & 2) and abs(c - l) <= eps and c < o and (h - o) > eps:
        return 1
    if (ps & 4) and abs(o - c) <= eps and abs(c - l) <= eps and (h - o) > 0.5 * rng:
        return 1
    return 0


def exit_signal(ctx, i):
    if not ctx.positions:
        return False
    e = min(p["entry_i"] for p in ctx.positions)
    return (i - e) >= int(ctx.p.hold)
